using Newtonsoft.Json;

namespace Valkyrie.WebApiProvider.Contracts
{
    public class SubmitToManualRequest //: SubmitToAutomaticRequest
    {
        /// <summary>
        ///  Customer API authentication key, generated by Valkyrie 
        /// </summary>
        [JsonProperty("api_key")]
        public string ApiKey { get; set; }
                
        [JsonProperty("submit_token")]
        public string SubmitToken { get; set; }

        /// <summary>
        /// Path of File on Origin
        /// </summary>
        [JsonProperty("file_path")]
        public string FilePath { get; set; }

         /// <summary>
         ///  Priority (1-10) 
         /// </summary>
        [JsonProperty("priority")]
        public int Priority { get; set; }
    }
}
